Fissiamo le notazioni: $P$ è il pattern e $T$ il testo, con $n=\abs{P}$ e $m=\abs{T}$; le
stringhe sono indicizzate a partire da~$1$.

Per il problema del pattern matching esatto i due termini del confronto sono
\[
  \text{naive}\quad
  \begin{cases}
    \Oh(n\cdot m) & \text{(quadratico)}\quad \emph{upper bound}\\[3pt]
    \Om(n+m)      & \text{(lineare)}\quad \emph{lower bound}
  \end{cases}
\]
Il limite superiore $\Oh(n\cdot m)$ è quello raggiunto dall'algoritmo naive; il limite
inferiore $\Om(n+m)$ è invece un limite del \emph{problema} (l'input va comunque letto per
intero), ed è esattamente ciò che Knuth--Morris--Pratt riesce a ottenere.

\begin{definizione*}[Pre-processing del pattern]
Il \emph{pre-processing} di $P$ consiste nel calcolare, per ogni prefisso di $P$, il più
lungo $\alpha$ che sia contemporaneamente prefisso e suffisso \emph{proprio} di quel
prefisso.
\end{definizione*}

\noindent E come lo si calcola? È la domanda a cui risponde il resto della pagina.

\begin{figure}[H]
  \centering
  \input{tikz/kmp-alfa-P.tikz}
  \caption{Per ogni prefisso $\sub{P}{1}{i}$ di $P$ si cerca il massimo $\alpha$ che ne sia
    al tempo stesso prefisso e suffisso.}
\end{figure}

\begin{osservazione}
Il pre-processing prende tempo \emph{lineare}.
\end{osservazione}

\noindent Lavoriamo allora su una generica stringa $S$, scrivendo $S_i \defeq \sub{S}{1}{i}$
per il suo prefisso $i$-esimo.

\begin{figure}[H]
  \centering
  \input{tikz/kmp-alfa-S.tikz}
  \caption{La stessa situazione sul prefisso $S_i=\sub{S}{1}{i}$: $\alpha$ compare una volta
    come prefisso di $S_i$ e una volta come suo suffisso, terminando in posizione $i$.}
\end{figure}

\begin{definizione*}[$\spv{i}(S)$]
Per $1\le i\le\abs{S}$,
\[
  \spv{i}(S) \defeq \max\set{\,k \;:\; 0\le k<i,\ \sub{S}{1}{k}=\sub{S}{i-k+1}{i}\,}
\]
è la lunghezza del massimo suffisso/prefisso \emph{proprio} del prefisso $i$-esimo di $S$.
In particolare $\spv{1}(S)=0$, perché la stringa vuota $\vuota$ è sempre un
prefisso-suffisso.
\end{definizione*}

\begin{figure}[H]
  \centering
  \input{tikz/kmp-bordo-del-bordo.tikz}
  \caption{Il passo ricorsivo: $\alpha$ è il massimo prefisso-suffisso di $S_{i-1}$ e
    $\beta$ è il massimo prefisso-suffisso di $\alpha$. Nel disegno $S[i]=a \ne b=S[k+1]$,
    quindi $\alpha$ non si estende e si ricade su $\beta$.}
\end{figure}

Per calcolare il massimo prefisso/suffisso di $S_i$ ci sono due casi. Posto
$k=\spv{i-1}(S)$ e $\alpha=\sub{S}{1}{k}$:
\begin{enumerate}
  \item (\emph{caso base}) se $S[i]=S[k+1]$ posso estendere $\alpha$ di un carattere, e
    \[
      \spv{i}(S) \;=\; \spv{i-1}(S)+1 ;
    \]
  \item altrimenti $\spv{i}(S)$ si ottiene ricorsivamente da $\spv{i-1}(S)$: il candidato
    successivo è $\beta$, il massimo prefisso-suffisso di $\alpha$, cioè
    $\abs{\beta}=\spv{k}(S)$, e si ripete il confronto fra $S[i]$ e $S[\abs{\beta}+1]$.
\end{enumerate}
Quante chiamate ricorsive innesca il caso 2)?

\begin{osservazione}[Problema]
Il caso 2) può innescare fino a $i$ chiamate ricorsive: per $i\in\set{1,\dots,n}$ l'ordine
del caso pessimo farebbe concludere che il pre-processing è \emph{quadratico}!
\end{osservazione}

\noindent Con l'analisi ammortizzata si vede invece che la somma delle operazioni su
\emph{tutte} le chiamate ricorsive, per $i\in\set{1,\dots,n}$, è \emph{lineare}.
